export const GLOSSARY_SHARD = Object.freeze({"airdrop":{"slug":"airdrop","cat":"basics","en":"Airdrop","contentLocale":"vi","term":"Airdrop","aka":["airdrop","săn airdrop","phát token miễn phí"],"short":"Airdrop là việc một dự án phát token miễn phí vào ví của người dùng đủ điều kiện, thường để thưởng người dùng sớm, phân phối token rộng hơn hoặc quảng bá dự án.","body":[["Có nhiều kiểu airdrop: dự án thưởng ví đã từng dùng sản phẩm trước một ngày chụp nhanh (snapshot), phát cho người giữ một token khác, hoặc yêu cầu hoàn thành nhiệm vụ. Một số sàn cũng phân phối token mới cho người dùng tham gia chương trình riêng như ",["Launchpool","launchpool"],"."],"Token airdrop thường bị bán mạnh ngay khi mở giao dịch, vì nhiều người nhận muốn chốt ngay. Một số dự án chia nhỏ phần airdrop và mở khóa dần theo thời gian.",["Airdrop cũng là mồi nhử phổ biến của kẻ lừa đảo. Token lạ tự xuất hiện trong ví kèm đường dẫn nhận thưởng, hoặc trang ",["web giả","phishing"]," yêu cầu bạn kết nối ví và ký lệnh, có thể là cái bẫy để rút sạch tài sản. Dự án thật không bao giờ hỏi ",["cụm từ khôi phục","seed-phrase"],". Thuế với token airdrop tùy quy định từng nước."]],"example":["Giả sử bạn đã dùng một ",["DEX","dex"]," trên ",["layer 2","layer-2"]," trong 6 tháng và tốn tổng cộng 15 ",["USDT","usdt"]," phí gas. Đến ngày phát, ví bạn đủ điều kiện nhận 400 token. Nếu token mở giao dịch ở 0,6 USDT, phần airdrop trị giá 240 USDT. Nếu bạn chờ và giá giảm 50% trong tuần đầu, phần đó còn 120 USDT. Trước khi nhận, bạn nên kiểm tra kỹ địa chỉ trang nhận thưởng từ kênh chính thức của dự án."],"mistakes":["Bấm vào đường dẫn đi kèm token lạ xuất hiện trong ví và ký lệnh cấp quyền.","Nhập cụm từ khôi phục vào một trang web để nhận airdrop.","Dùng ví chính chứa nhiều tài sản để thử các dự án airdrop chưa rõ nguồn gốc."],"faq":[{"q":"Làm sao biết airdrop là thật hay lừa đảo?","a":"Chỉ tin thông tin từ kênh chính thức của dự án, kiểm tra kỹ tên miền và không bao giờ nhập cụm từ khôi phục. Token tự xuất hiện kèm lời mời nhận thưởng thường là dấu hiệu lừa đảo."},{"q":"Săn airdrop có tốn tiền không?","a":"Thường có, vì bạn phải trả phí gas khi dùng sản phẩm để đủ điều kiện. Không có gì đảm bảo dự án sẽ phát airdrop hoặc bạn sẽ được nhận."}],"title":"Airdrop là gì? Cách nhận và tránh lừa đảo","description":"Airdrop crypto là gì, dự án phát token miễn phí thế nào, vì sao giá hay giảm sau airdrop và cách tránh bẫy lừa đảo.","related":[["phishing","Lừa đảo giả mạo (Phishing)","Phishing là hình thức lừa đảo giả mạo sàn, ví, dự án hoặc người quen để lừa bạn nhập mật khẩu, mã 2FA, cụm từ khôi phục hoặc ký giao dịch có hại."],["token-approval","Cấp quyền token (Token approval)","Cấp quyền token là thao tác cho phép một hợp đồng thông minh được chi tiêu một lượng token nhất định trong ví của bạn, bắt buộc trước khi swap hay gửi token vào nhiều ứng dụng DeFi."],["governance-token","Token quản trị (Governance token)","Token quản trị là token cho người nắm giữ quyền đề xuất và bỏ phiếu về các thay đổi của một giao thức hay DAO, ví dụ UNI của Uniswap hay AAVE của Aave."],["launchpool","Launchpool","Launchpool là chương trình trên sàn cho phép bạn khóa token như BNB hay stablecoin trong một thời gian để nhận miễn phí token mới của dự án sắp niêm yết."],["rug-pull","Rug pull (Rút thảm)","Rug pull là khi đội ngũ dự án crypto đột ngột rút thanh khoản, bán tháo token hoặc biến mất cùng tiền của nhà đầu tư, khiến giá token gần như về 0."]],"lesson":{"id":"E11","slug":"scam-red-flags","ep":11,"title":"Có người bảo giúp bạn kiếm tiền. Hãy xem họ đòi hỏi điều gì trước đã."},"coin":null,"tool":null,"cta":false},"centralized-exchange":{"slug":"centralized-exchange","cat":"trading","en":"Centralized exchange (CEX)","contentLocale":"vi","term":"Sàn giao dịch tập trung (CEX)","aka":["CEX","sàn tập trung","centralized exchange","sàn CEX"],"short":"Sàn giao dịch tập trung (CEX) là nền tảng do một công ty vận hành, giữ tài sản của người dùng và khớp lệnh mua bán trên sổ lệnh nội bộ, như Binance, OKX, Bybit hay Bitget.","body":[["Khi bạn nạp tiền vào CEX, sàn giữ coin thay bạn (lưu ký) và ghi số dư vào tài khoản. Lệnh mua bán được khớp trong hệ thống của sàn, nhanh và rẻ, không cần trả ",["phí gas","gas-fee"]," cho từng lệnh. Chỉ khi rút ra ví ngoài, giao dịch mới được ghi lên ",["blockchain","blockchain"],"."],["CEX thường cung cấp nhiều sản phẩm: ",["giao dịch spot","spot-trading"],", ",["hợp đồng tương lai vĩnh cửu","perpetual-futures"],", ",["P2P","p2p-trading"]," để mua bằng tiền pháp định, ",["staking","staking"],", copy trade. Hầu hết yêu cầu xác minh danh tính (KYC). Phí giao dịch theo mô hình maker/taker và giảm theo cấp VIP, khác nhau giữa các sàn."],"Đổi lại sự tiện lợi, bạn chấp nhận rủi ro đối tác: sàn có thể bị hack, đóng băng tài khoản hoặc gặp vấn đề tài chính. Hãy xem sàn có công bố bằng chứng dự trữ (proof of reserves), giấy phép ở các khu vực nó hoạt động, và cân nhắc không để toàn bộ tài sản ở một nơi."],"example":"Giả sử bạn mua 1.000 USDT tiền ETH trên một CEX với phí taker 0,1%, phí là 1 USDT. Cùng giao dịch trên một DEX ở Ethereum mạng chính có thể tốn phí pool 0,3% (3 USDT) cộng phí gas vài USDT. Nhưng nếu bạn để 10.000 USDT trên một sàn duy nhất và sàn đó tạm dừng rút tiền, toàn bộ 10.000 USDT bị kẹt, trong khi tài sản trong ví tự lưu ký vẫn do bạn kiểm soát.","mistakes":["Để toàn bộ tài sản dài hạn trên một sàn duy nhất.","Không bật xác thực hai lớp và danh sách địa chỉ rút tiền cho tài khoản sàn.","Nghĩ rằng mọi sàn đều có cùng mức phí, sản phẩm và quy định."],"faq":[{"q":"CEX khác DEX thế nào?","a":"CEX do công ty vận hành và giữ tài sản thay bạn, còn DEX chạy bằng hợp đồng thông minh và bạn giao dịch trực tiếp từ ví của mình. CEX thường nhanh và dễ dùng hơn, DEX cho bạn tự kiểm soát tài sản."},{"q":"Để coin trên sàn có an toàn không?","a":"Tùy vào độ tin cậy của sàn và cách bạn bảo mật tài khoản. Nhiều người chỉ để trên sàn phần cần giao dịch và giữ phần dài hạn trong ví tự lưu ký."}],"title":"Sàn tập trung (CEX) là gì? Cách hoạt động","description":"Sàn giao dịch tập trung CEX là gì, khác DEX ra sao, có những sản phẩm nào và cần lưu ý gì về an toàn tài sản.","related":[["dex","Sàn phi tập trung (DEX)","Sàn phi tập trung (DEX) là nơi giao dịch crypto trực tiếp từ ví của bạn qua hợp đồng thông minh, không cần nạp tiền vào tài khoản của một công ty trung gian."],["kyc","KYC (xác minh danh tính khách hàng)","KYC là quy trình sàn giao dịch hoặc tổ chức tài chính xác minh danh tính người dùng bằng giấy tờ tùy thân, ảnh khuôn mặt và đôi khi là địa chỉ cư trú."],["proof-of-reserves","Bằng chứng dự trữ (Proof of reserves)","Bằng chứng dự trữ là báo cáo sàn công bố để chứng minh họ đang nắm giữ đủ tài sản on-chain tương ứng với số dư khách hàng, thường kèm cách để từng người tự kiểm tra."],["custodial-wallet","Ví lưu ký (Custodial wallet)","Ví lưu ký là ví mà một bên thứ ba, thường là sàn giao dịch, giữ khóa riêng tư thay bạn; bạn truy cập tài sản bằng tài khoản và mật khẩu thay vì seed phrase."],["maker-taker-fees","Phí maker và phí taker (Maker/Taker fee)","Phí maker và phí taker là hai mức phí giao dịch khác nhau: maker trả phí khi lệnh của bạn nằm chờ trên sổ lệnh và tạo thêm thanh khoản, taker trả phí khi lệnh của bạn khớp ngay với lệnh có sẵn."]],"lesson":{"id":"E03","slug":"exchange-vs-wallet","ep":3,"title":"Coin của tôi ở đâu: Sàn giao dịch và ví khác nhau thế nào?"},"coin":null,"tool":"/exchanges","cta":true},"support-and-resistance":{"slug":"support-and-resistance","cat":"trading","en":"Support and resistance","contentLocale":"vi","term":"Hỗ trợ và kháng cự (Support và Resistance)","aka":["vùng hỗ trợ","vùng kháng cự","support resistance","hỗ trợ kháng cự"],"short":"Hỗ trợ và kháng cự là các vùng giá mà trước đây giá thường dừng giảm (hỗ trợ) hoặc dừng tăng (kháng cự), do lực mua hoặc lực bán tập trung ở đó.","body":["Vùng hỗ trợ hình thành khi nhiều người sẵn sàng mua ở một mức giá, chẳng hạn mức giá từng bật lên nhiều lần. Vùng kháng cự hình thành khi nhiều người muốn bán, chẳng hạn đỉnh cũ hoặc các con số tròn. Nên nghĩ về chúng như một vùng chứ không phải một đường chính xác.",["Khi giá phá vỡ một vùng kháng cự và đi lên, vùng đó đôi khi trở thành hỗ trợ mới, và ngược lại. Nhiều người giao dịch dùng các vùng này để đặt ",["lệnh giới hạn","limit-order"],", ",["cắt lỗ","stop-loss"]," và ",["chốt lời","take-profit"],"."],"Hỗ trợ và kháng cự không đảm bảo điều gì. Giá có thể xuyên qua rồi quay lại, gọi là phá vỡ giả. Vì nhiều người đặt cắt lỗ ngay dưới hỗ trợ, giá đôi khi quét qua đó trước khi đảo chiều."],"example":["Giả sử SOL đã ba lần bật lên từ vùng 140-142 ",["USDT","usdt"]," trong hai tháng, và hai lần bị chặn ở vùng 175-178 USDT. Bạn xem 140-142 là hỗ trợ, 175-178 là kháng cự. Nếu mua ở 145, đặt cắt lỗ ở 136 (dưới hỗ trợ một khoảng) và chốt lời ở 172 (trước kháng cự), rủi ro là 9 USDT mỗi SOL và lợi nhuận tiềm năng là 27 USDT, tỷ lệ 1:3."],"mistakes":["Vẽ hỗ trợ kháng cự thành một đường giá chính xác thay vì một vùng.","Đặt cắt lỗ đúng ngay tại mức hỗ trợ, nơi nhiều lệnh khác cũng nằm.","Tin rằng một vùng hỗ trợ đã giữ nhiều lần thì sẽ giữ mãi."],"faq":[{"q":"Làm sao xác định vùng hỗ trợ và kháng cự?","a":"Tìm các mức giá mà giá từng đảo chiều nhiều lần, các đỉnh đáy cũ rõ ràng và các số tròn. Khung thời gian lớn thường cho vùng đáng tin hơn."},{"q":"Hỗ trợ bị phá thì sao?","a":"Khi giá đóng cửa rõ ràng dưới vùng hỗ trợ, vùng đó có thể trở thành kháng cự. Đây là lúc kế hoạch cắt lỗ của bạn phát huy tác dụng."}],"title":"Hỗ trợ và kháng cự là gì? Cách xác định trong crypto","description":"Hỗ trợ và kháng cự là gì, cách vẽ các vùng giá quan trọng và dùng chúng để đặt cắt lỗ, chốt lời hợp lý.","related":[["candlestick-chart","Biểu đồ nến (Candlestick chart)","Biểu đồ nến là loại biểu đồ giá trong đó mỗi cây nến thể hiện giá mở cửa, giá cao nhất, giá thấp nhất và giá đóng cửa của một tài sản trong một khung thời gian."],["stop-loss","Lệnh cắt lỗ (Stop-loss)","Lệnh cắt lỗ (stop-loss) là lệnh tự động đóng vị thế khi giá chạm một mức bạn đặt trước, nhằm giới hạn khoản lỗ trong trường hợp thị trường đi ngược kỳ vọng."],["limit-order","Lệnh giới hạn (Limit order)","Lệnh giới hạn (limit order) là lệnh mua hoặc bán ở mức giá bạn chỉ định hoặc tốt hơn; lệnh chỉ khớp khi thị trường chạm mức giá đó, nếu không sẽ nằm chờ trong sổ lệnh."],["all-time-high","Đỉnh lịch sử (All-time high - ATH)","Đỉnh lịch sử (all-time high, ATH) là mức giá cao nhất mà một tài sản từng đạt được kể từ khi bắt đầu giao dịch, thường được tính theo một đồng tiền định giá như USD hoặc USDT."]],"lesson":{"id":"E15","slug":"read-a-candlestick","ep":15,"title":"Một cây nến: bốn điều nó thực sự nói cho bạn là gì?"},"coin":null,"tool":null,"cta":false},"dollar-cost-averaging":{"slug":"dollar-cost-averaging","cat":"trading","en":"Dollar-cost averaging (DCA)","contentLocale":"vi","term":"DCA (Trung bình giá)","aka":["DCA","dollar-cost averaging","mua trung bình giá","đầu tư định kỳ"],"short":"DCA (dollar-cost averaging) là chiến lược mua một số tiền cố định của một tài sản theo lịch đều đặn, bất kể giá lên hay xuống, để làm mềm tác động của biến động giá.","body":["Thay vì dồn toàn bộ vốn vào một thời điểm, bạn chia ra và mua đều đặn, ví dụ mỗi tuần hoặc mỗi tháng. Khi giá thấp, cùng số tiền mua được nhiều coin hơn; khi giá cao, mua được ít hơn. Giá vốn trung bình của bạn vì thế không phụ thuộc vào một lần mua duy nhất.","DCA giúp giảm áp lực phải đoán đáy và hạn chế quyết định theo cảm xúc. Nhiều sàn có tính năng mua định kỳ tự động trong mục spot hoặc mục bot. Tuy vậy, DCA không loại bỏ rủi ro: nếu tài sản giảm giá kéo dài, bạn vẫn lỗ.","Chi phí cũng cần tính: phí giao dịch mỗi lần mua và spread có thể ăn mòn kết quả nếu bạn mua quá nhỏ và quá dày. Hãy chọn tần suất và số tiền phù hợp với thu nhập của bạn."],"example":["Giả sử bạn mua 100 ",["USDT","usdt"]," ",["BTC","bitcoin"]," mỗi tháng trong 4 tháng, với giá lần lượt 60.000, 50.000, 40.000 và 50.000 USDT. Số BTC nhận được là 0,001667 + 0,002 + 0,0025 + 0,002 = 0,008167 BTC cho 400 USDT. Giá vốn trung bình khoảng 400 / 0,008167 ≈ 48.980 USDT, thấp hơn trung bình cộng của bốn mức giá (50.000 USDT)."],"mistakes":["Nghĩ rằng DCA đảm bảo có lãi, trong khi nó chỉ làm mềm thời điểm mua.","Dừng DCA đúng lúc giá giảm mạnh, chính là lúc chiến lược mua được giá rẻ nhất.","DCA vào coin chưa tìm hiểu, chỉ vì nghĩ rằng mua đều sẽ an toàn."],"faq":[{"q":"DCA là gì trong crypto?","a":"DCA là mua đều đặn một số tiền cố định theo lịch, ví dụ 50 USDT mỗi tuần. Cách này giúp giá vốn trung bình không phụ thuộc vào một thời điểm mua."},{"q":"Nên DCA theo tuần hay theo tháng?","a":"Cả hai đều được. Điều quan trọng là giữ kỷ luật và để phí mỗi lần mua chiếm tỷ lệ nhỏ so với số tiền mua."},{"q":"DCA có tốt hơn mua một lần không?","a":"Không phải lúc nào cũng vậy. Nếu giá tăng đều, mua một lần từ đầu có thể cho kết quả tốt hơn; DCA chủ yếu giúp giảm rủi ro mua sai thời điểm."}],"title":"DCA là gì? Chiến lược mua trung bình giá crypto","description":"DCA là gì, cách mua định kỳ giúp làm mềm biến động giá, ví dụ tính giá vốn trung bình và những hiểu lầm thường gặp.","related":[["hodl","HODL (giữ dài hạn)","HODL là cách nói trong cộng đồng crypto chỉ việc giữ tài sản lâu dài bất chấp biến động ngắn hạn, bắt nguồn từ một lỗi chính tả của chữ hold trên diễn đàn Bitcoin năm 2013."],["volatility","Biến động giá (Volatility)","Biến động giá (volatility) là mức độ và tốc độ thay đổi giá của một tài sản trong một khoảng thời gian; biến động càng cao thì giá dao động lên xuống càng mạnh."],["position-sizing","Quản lý khối lượng vị thế (Position sizing)","Position sizing là cách xác định bạn nên mở một lệnh lớn bao nhiêu, dựa trên số tiền bạn chấp nhận mất nếu lệnh chạm cắt lỗ."],["grid-trading-bot","Bot giao dịch lưới (grid bot)","Bot giao dịch lưới là công cụ tự động đặt sẵn nhiều lệnh mua và bán ở các mức giá cách đều trong một vùng, để kiếm lời từ những lần giá dao động lên xuống."],["spot-trading","Giao dịch spot (Spot trading)","Giao dịch spot (spot trading) là mua bán tài sản crypto để nhận ngay quyền sở hữu thật ở giá hiện tại, không dùng hợp đồng và mặc định không có đòn bẩy."]],"lesson":{"id":"E16","slug":"position-sizing-basics","ep":16,"title":"Xác định mức có thể mất trước khi quyết định mua bao nhiêu"},"coin":null,"tool":null,"cta":true},"usdt-margined-futures":{"slug":"usdt-margined-futures","cat":"derivatives","en":"USDT-margined (linear) futures","contentLocale":"vi","term":"Hợp đồng ký quỹ bằng USDT (USDT-M)","aka":["USDT-M","hợp đồng tuyến tính","linear futures","USDⓈ-M"],"short":"Hợp đồng ký quỹ bằng USDT (USDT-M, hay hợp đồng tuyến tính) là hợp đồng tương lai mà ký quỹ, lãi lỗ và phí đều tính bằng USDT.","body":[["Đây là loại hợp đồng phổ biến nhất với người giao dịch cá nhân. Lãi lỗ tuyến tính: giá thay đổi bao nhiêu ",["USDT","usdt"]," thì vị thế lãi hoặc lỗ đúng bấy nhiêu nhân với số lượng coin. Bạn dễ tính rủi ro hơn ",["Coin-M","coin-margined-futures"]," vì ký quỹ không ",["biến động","volatility"]," theo giá coin."],["Một tài khoản USDT có thể giao dịch rất nhiều cặp khác nhau, và với ",["ký quỹ chéo","cross-margin"],", lãi lỗ của các vị thế có thể bù trừ nhau. Một số sàn dùng thêm ",["USDC","usdc"]," làm ký quỹ cho hợp đồng tuyến tính tương tự."],["Rủi ro riêng của USDT-M là phụ thuộc vào ",["stablecoin","stablecoin"],". Nếu USDT lệch khỏi mức 1 USD, giá trị thực của ký quỹ và lợi nhuận cũng thay đổi theo."]],"example":"Giả sử bạn long 3 SOL hợp đồng USDT-M ở giá 150 USDT với đòn bẩy 5x. Giá trị vị thế là 450 USDT, ký quỹ ban đầu 90 USDT. Nếu SOL lên 162 USDT, lãi là 3 × 12 = 36 USDT, tức 40% trên ký quỹ. Nếu SOL giảm xuống 138 USDT, bạn lỗ đúng 36 USDT. Lãi và lỗ đối xứng, không phụ thuộc giá USDT của ký quỹ.","mistakes":["Nhầm số lượng hợp đồng với số tiền USDT khi nhập lệnh.","Để toàn bộ USDT ở chế độ ký quỹ chéo mà không biết một vị thế lỗ có thể kéo theo cả tài khoản.","Quên rằng phí funding cũng được trừ trực tiếp vào số dư USDT."],"faq":[{"q":"USDT-M là gì?","a":"Là hợp đồng tương lai ký quỹ và thanh toán bằng USDT. Lãi lỗ tuyến tính nên dễ tính toán, phù hợp với người mới."},{"q":"Nên chọn USDT-M hay Coin-M?","a":"USDT-M phù hợp khi bạn muốn tính lãi lỗ theo USD đơn giản. Coin-M phù hợp khi bạn muốn giữ ký quỹ và lợi nhuận bằng coin."}],"title":"Hợp đồng USDT-M là gì? Futures ký quỹ bằng USDT","description":"Hợp đồng ký quỹ bằng USDT (USDT-M) là gì, vì sao lãi lỗ tuyến tính dễ tính và khác Coin-M ở những điểm nào.","related":[["coin-margined-futures","Hợp đồng ký quỹ bằng coin (Coin-M)","Hợp đồng ký quỹ bằng coin (Coin-M, hay hợp đồng nghịch đảo) là hợp đồng tương lai mà ký quỹ và lãi lỗ được tính bằng chính đồng coin cơ sở, ví dụ BTC, thay vì USDT."],["perpetual-futures","Hợp đồng tương lai vĩnh cửu (Perpetual)","Hợp đồng tương lai vĩnh cửu (perpetual) là hợp đồng tương lai không có ngày đáo hạn, dùng cơ chế funding rate để giữ giá hợp đồng bám sát giá spot."],["usdt","USDT (Tether)","USDT là stablecoin do công ty Tether phát hành, neo theo tỷ lệ 1 USDT bằng 1 USD và là đồng ổn định được giao dịch nhiều nhất trên các sàn crypto."],["cross-margin","Ký quỹ chéo (Cross margin)","Ký quỹ chéo là chế độ trong đó toàn bộ số dư khả dụng của tài khoản được dùng chung làm ký quỹ cho các vị thế, giúp hạn chế thanh lý sớm nhưng có thể khiến bạn mất cả tài khoản."]],"lesson":{"id":"E18","slug":"spot-vs-futures","ep":18,"title":"Giao ngay và tương lai: bạn không mua cùng một thứ"},"coin":{"slug":"tether","name":"Tether","symbol":"USDT"},"tool":null,"cta":true},"open-interest":{"slug":"open-interest","cat":"derivatives","en":"Open interest","contentLocale":"vi","term":"Hợp đồng mở (Open interest)","aka":["open interest","OI","khối lượng hợp đồng mở"],"short":"Hợp đồng mở (open interest, OI) là tổng số lượng hoặc giá trị các hợp đồng phái sinh đang còn mở và chưa được đóng hay tất toán tại một thời điểm.","body":["Mỗi hợp đồng có một bên long và một bên short, nên OI đếm số hợp đồng chứ không cộng cả hai bên. Khi một người mở long mới và một người mở short mới, OI tăng. Khi cả hai bên cùng đóng vị thế, OI giảm. Khi một bên chuyển vị thế cho người mới, OI không đổi.",["Volume đo lượng giao dịch trong một khoảng thời gian; OI đo lượng vị thế đang tồn tại. OI tăng cùng giá tăng thường cho thấy tiền mới đang đổ vào; OI giảm mạnh trong ",["biến động","volatility"]," lớn thường là dấu hiệu nhiều vị thế bị đóng hoặc ",["thanh lý","liquidation"],"."],"OI có thể tính bằng số coin hoặc USD. Khi tính bằng USD, OI tăng chỉ vì giá tăng, nên hãy xem cả hai đơn vị."],"example":["Giả sử OI của ",["BTC","bitcoin"]," perp trên một sàn là 50.000 BTC. Trong một ngày, người giao dịch mở thêm 4.000 BTC vị thế mới và đóng 1.500 BTC vị thế cũ. OI cuối ngày là 50.000 + 4.000 - 1.500 = 52.500 BTC. Nếu giá BTC từ 60.000 lên 62.000 ",["USDT","usdt"],", OI tính bằng USD tăng từ 3 tỷ lên khoảng 3,255 tỷ USDT."],"mistakes":["Nhầm open interest với volume giao dịch.","Coi OI tăng là tín hiệu tăng giá, trong khi OI tăng có thể do short mở thêm.","Chỉ xem OI tính bằng USD mà quên phần tăng do giá."],"faq":[{"q":"Open interest tăng có ý nghĩa gì?","a":"Nghĩa là có thêm vị thế mới được mở và nhiều đòn bẩy hơn trong thị trường. Nó không tự cho biết phe long hay short đang chiếm ưu thế."},{"q":"Open interest khác volume thế nào?","a":"Volume đếm lượng giao dịch trong một khoảng thời gian, OI đếm lượng vị thế còn mở tại một thời điểm."}],"title":"Open interest (OI) là gì? Hợp đồng mở trong crypto","description":"Open interest là gì, khác volume thế nào và cách đọc OI tăng giảm cùng giá để hiểu dòng tiền vào thị trường phái sinh.","related":[["trading-volume","Khối lượng giao dịch (Volume)","Khối lượng giao dịch là tổng giá trị hoặc số lượng một tài sản đã được mua bán trong một khoảng thời gian, thường tính trong 24 giờ."],["funding-rate","Funding rate (Tỷ lệ funding)","Funding rate là khoản thanh toán định kỳ giữa phe long và phe short trong hợp đồng tương lai vĩnh cửu, giúp giá hợp đồng bám sát giá spot."],["long-short-ratio","Tỷ lệ Long/Short (Long/short ratio)","Tỷ lệ long/short là chỉ số so sánh số tài khoản hoặc khối lượng vị thế đang long với số đang short trên một sàn, dùng để đọc tâm lý người giao dịch phái sinh."],["liquidation","Thanh lý (Liquidation)","Thanh lý (hay cháy tài khoản) là khi sàn tự động đóng vị thế có đòn bẩy của bạn vì ký quỹ không còn đủ đáp ứng mức ký quỹ duy trì."]],"lesson":null,"coin":null,"tool":"/funding-rates","cta":false},"hot-wallet":{"slug":"hot-wallet","cat":"wallets-security","en":"Hot wallet","contentLocale":"vi","term":"Ví nóng (Hot wallet)","aka":["hot wallet","ví online"],"short":"Ví nóng là ví crypto có khóa riêng tư nằm trên thiết bị hoặc máy chủ kết nối internet, giúp giao dịch nhanh nhưng dễ bị tấn công từ xa hơn ví lạnh.","body":["Ví trên điện thoại như Trust Wallet, tiện ích trình duyệt như MetaMask, hay ví của sàn mà bạn đang dùng đều là ví nóng. Vì khóa luôn sẵn sàng trên thiết bị có mạng, bạn có thể gửi, nhận, swap hay kết nối DApp chỉ trong vài giây.",["Điểm yếu là bề mặt tấn công rộng: mã độc trên máy tính, tiện ích giả, trang web lừa đảo yêu cầu ký giao dịch, hoặc điện thoại bị mất khi đang mở khóa. Các sàn lớn cũng dùng ví nóng cho nhu cầu rút tiền hằng ngày và giữ phần lớn tài sản trong ",["ví lạnh","cold-wallet"],"."],"Cách dùng hợp lý là coi ví nóng như ví tiền mang theo người: chỉ để số tiền bạn cần cho giao dịch gần, phần còn lại cất ở nơi an toàn hơn."],"example":["Giả sử bạn có tổng cộng 10.000 ",["USDT","usdt"],". Bạn để 800 USDT trong ví nóng MetaMask để thử các DApp và swap trên ",["DEX","dex"],", còn 9.200 USDT nằm trong ",["ví cứng","hardware-wallet"],". Một ngày bạn lỡ ký một giao dịch trên trang ",["giả mạo","phishing"]," và mất toàn bộ ví nóng. Thiệt hại là 800 USDT, tức 8% tổng tài sản, thay vì mất cả 10.000 USDT nếu mọi thứ để chung một chỗ."],"mistakes":["Giữ toàn bộ tài sản lâu dài trong một ví nóng trên điện thoại cũng dùng để cài app lạ.","Cài tiện ích ví từ kết quả quảng cáo trên công cụ tìm kiếm mà không kiểm tra nhà phát hành.","Dùng chung một ví nóng cho cả việc thử dự án mới lẫn cất trữ tiền chính."],"faq":[{"q":"Ví nóng và ví lạnh khác nhau thế nào?","a":"Ví nóng giữ khóa trên thiết bị có kết nối internet nên tiện nhưng dễ bị tấn công hơn. Ví lạnh giữ khóa ngoại tuyến, an toàn hơn nhưng thao tác chậm hơn."},{"q":"Tài khoản trên sàn có phải ví nóng không?","a":"Về mặt kỹ thuật, sàn giữ tài sản của bạn và dùng cả ví nóng lẫn ví lạnh. Với bạn, đó là ví lưu ký vì bạn không giữ khóa riêng tư."}],"title":"Ví nóng (hot wallet) là gì? Ưu và nhược điểm","description":"Ví nóng (hot wallet) là gì, vì sao tiện nhưng rủi ro hơn ví lạnh, và nên để bao nhiêu tiền trong ví nóng.","related":[["cold-wallet","Ví lạnh (Cold wallet)","Ví lạnh là cách lưu khóa riêng tư hoàn toàn ngoại tuyến, ví dụ trên ví cứng hoặc thiết bị không bao giờ kết nối mạng, để giảm tối đa rủi ro bị hack từ xa."],["hardware-wallet","Ví cứng (Hardware wallet)","Ví cứng là thiết bị vật lý nhỏ chuyên lưu khóa riêng tư ngoại tuyến và ký giao dịch bên trong thiết bị, nên khóa không bao giờ lộ ra máy tính hay điện thoại."],["non-custodial-wallet","Ví phi lưu ký (Non-custodial wallet)","Ví phi lưu ký là loại ví crypto mà bạn tự giữ khóa riêng tư và cụm từ khôi phục, nên chỉ bạn mới có quyền ký giao dịch và di chuyển tài sản."],["phishing","Lừa đảo giả mạo (Phishing)","Phishing là hình thức lừa đảo giả mạo sàn, ví, dự án hoặc người quen để lừa bạn nhập mật khẩu, mã 2FA, cụm từ khôi phục hoặc ký giao dịch có hại."]],"lesson":{"id":"E03","slug":"exchange-vs-wallet","ep":3,"title":"Coin của tôi ở đâu: Sàn giao dịch và ví khác nhau thế nào?"},"coin":null,"tool":null,"cta":false},"seed-phrase":{"slug":"seed-phrase","cat":"wallets-security","en":"Seed phrase (recovery phrase)","contentLocale":"vi","term":"Cụm từ khôi phục (Seed phrase)","aka":["seed phrase","recovery phrase","cụm từ bí mật","12 từ khôi phục"],"short":"Cụm từ khôi phục là chuỗi 12 hoặc 24 từ tiếng Anh dùng để tạo lại toàn bộ khóa riêng tư của ví, nên ai có nó là có toàn quyền với tài sản trong ví.","body":[["Khi tạo ",["ví phi lưu ký","non-custodial-wallet"],", ứng dụng sinh ngẫu nhiên một dãy từ theo chuẩn BIP-39. Từ dãy này, ví tính ra mọi ",["khóa riêng tư","private-key"]," và địa chỉ của bạn trên nhiều ",["blockchain","blockchain"],". Đổi điện thoại hay ví hỏng, chỉ cần nhập đúng các từ theo đúng thứ tự là ví được khôi phục."],"Vì quyền lực lớn như vậy, cụm từ khôi phục là mục tiêu số một của kẻ lừa đảo. Không ví, sàn hay đội hỗ trợ chân chính nào yêu cầu bạn cung cấp nó. Bất kỳ trang web, tin nhắn hay “nhân viên” nào hỏi cụm từ đều là lừa đảo.","Cách giữ phổ biến là viết tay lên giấy hoặc khắc lên kim loại, cất ở nơi kín đáo, có thể làm hai bản ở hai địa điểm. Không chụp ảnh, không lưu trong email, ghi chú hay cloud."],"example":["Giả sử ví của bạn có 12 từ và chứa 4.000 ",["USDT","usdt"],". Bạn viết 12 từ lên giấy, đánh số 1 đến 12. Sau này khi khôi phục, bạn nhập nhầm thứ tự từ số 5 và số 6: ví vẫn có thể báo cụm từ không hợp lệ, hoặc mở ra một ví trống hoàn toàn khác. Đúng 12 từ, đúng thứ tự thì 4.000 USDT mới hiện lại."],"mistakes":["Lưu cụm từ khôi phục trong ảnh chụp màn hình, ghi chú điện thoại hoặc tin nhắn gửi cho chính mình.","Nhập cụm từ vào trang web “đồng bộ ví” hay “nhận airdrop” do người lạ gửi link.","Chỉ có một bản sao duy nhất, để mất hoặc hư hỏng là mất ví vĩnh viễn."],"faq":[{"q":"Cụm từ khôi phục và khóa riêng tư khác nhau thế nào?","a":"Khóa riêng tư điều khiển một địa chỉ cụ thể. Cụm từ khôi phục là gốc sinh ra tất cả khóa riêng tư của ví, nên nó còn quan trọng hơn."},{"q":"Quên cụm từ khôi phục có lấy lại được không?","a":"Nếu ví vẫn đang mở trên thiết bị, bạn có thể xem lại hoặc chuyển tiền sang ví mới ngay. Nếu đã mất cả thiết bị lẫn cụm từ, không ai có thể khôi phục ví cho bạn."}],"title":"Seed phrase là gì? Cụm từ khôi phục ví crypto","description":"Cụm từ khôi phục (seed phrase) là gì, hoạt động ra sao, vì sao không bao giờ được đưa cho ai và cách cất giữ an toàn.","related":[["private-key","Khóa riêng tư (Private key)","Khóa riêng tư là một số bí mật rất lớn dùng để ký giao dịch và chứng minh bạn sở hữu một địa chỉ ví; ai biết khóa này có thể chuyển toàn bộ tài sản đi."],["non-custodial-wallet","Ví phi lưu ký (Non-custodial wallet)","Ví phi lưu ký là loại ví crypto mà bạn tự giữ khóa riêng tư và cụm từ khôi phục, nên chỉ bạn mới có quyền ký giao dịch và di chuyển tài sản."],["phishing","Lừa đảo giả mạo (Phishing)","Phishing là hình thức lừa đảo giả mạo sàn, ví, dự án hoặc người quen để lừa bạn nhập mật khẩu, mã 2FA, cụm từ khôi phục hoặc ký giao dịch có hại."],["hardware-wallet","Ví cứng (Hardware wallet)","Ví cứng là thiết bị vật lý nhỏ chuyên lưu khóa riêng tư ngoại tuyến và ký giao dịch bên trong thiết bị, nên khóa không bao giờ lộ ra máy tính hay điện thoại."]],"lesson":{"id":"E11","slug":"scam-red-flags","ep":11,"title":"Có người bảo giúp bạn kiếm tiền. Hãy xem họ đòi hỏi điều gì trước đã."},"coin":null,"tool":null,"cta":false},"public-key":{"slug":"public-key","cat":"wallets-security","en":"Public key","contentLocale":"vi","term":"Khóa công khai (Public key)","aka":["public key"],"short":"Khóa công khai là khóa được tính ra từ khóa riêng tư, có thể chia sẻ công khai, dùng để mọi người xác minh chữ ký của bạn và để tạo ra địa chỉ ví.","body":[["Mật mã khóa công khai hoạt động theo một chiều: từ ",["khóa riêng tư","private-key"]," tính ra khóa công khai rất dễ, nhưng đi ngược lại thì gần như không thể. Nhờ vậy bạn có thể để lộ khóa công khai mà tài sản vẫn an toàn."],["Trên ",["Bitcoin","bitcoin"]," và ",["Ethereum","ethereum"],", ",["địa chỉ ví","wallet-address"]," thường là dạng rút gọn đã băm của khóa công khai, chứ không phải chính khóa công khai. Khi bạn ký giao dịch, các ",["nút mạng","node"]," dùng khóa công khai để kiểm tra chữ ký có đúng do khóa riêng tư tương ứng tạo ra hay không."],["Người dùng thông thường hiếm khi phải thao tác với khóa công khai. Bạn sẽ gặp nó khi thiết lập ",["ví đa chữ ký","multisig-wallet"],", dùng khóa công khai mở rộng (xpub) để theo dõi số dư, hoặc xác minh tin nhắn đã ký."]],"example":"Giả sử bạn muốn một phần mềm kế toán theo dõi số dư của 20 địa chỉ Bitcoin trong ví cứng mà không cấp quyền chi tiêu. Bạn xuất khóa công khai mở rộng xpub và nhập vào phần mềm. Phần mềm thấy tổng 0,35 BTC và mọi giao dịch đến, đi của cả 20 địa chỉ, nhưng không thể gửi đi dù chỉ 1 satoshi vì không có khóa riêng tư. Lưu ý ai có xpub cũng xem được toàn bộ lịch sử ví.","mistakes":["Nhầm khóa công khai với khóa riêng tư và hoảng sợ khi chia sẻ địa chỉ nhận tiền.","Chia sẻ xpub lung tung mà không biết nó tiết lộ toàn bộ số dư và lịch sử giao dịch.","Nghĩ rằng khóa công khai và địa chỉ ví luôn là một chuỗi giống hệt nhau."],"faq":[{"q":"Chia sẻ khóa công khai có nguy hiểm không?","a":"Không mất tiền, vì không ai chi tiêu được chỉ bằng khóa công khai. Nhưng nó có thể làm lộ quyền riêng tư về số dư và lịch sử giao dịch."},{"q":"Khóa công khai có phải địa chỉ ví không?","a":"Không hoàn toàn. Địa chỉ ví thường được tạo ra bằng cách băm và mã hóa khóa công khai thành chuỗi ngắn gọn hơn."}],"title":"Khóa công khai (public key) là gì? Khác gì địa chỉ ví","description":"Khóa công khai là gì, liên hệ với khóa riêng tư và địa chỉ ví ra sao, và vì sao chia sẻ public key không làm mất tiền.","related":[["private-key","Khóa riêng tư (Private key)","Khóa riêng tư là một số bí mật rất lớn dùng để ký giao dịch và chứng minh bạn sở hữu một địa chỉ ví; ai biết khóa này có thể chuyển toàn bộ tài sản đi."],["wallet-address","Địa chỉ ví (Wallet address)","Địa chỉ ví là chuỗi ký tự công khai đại diện cho nơi nhận crypto trên một blockchain cụ thể, giống số tài khoản ngân hàng nhưng gắn với từng mạng lưới."],["blockchain","Blockchain (chuỗi khối)","Blockchain (chuỗi khối) là một sổ cái số được chia sẻ, trong đó các giao dịch được gom thành từng khối và nối với nhau theo thứ tự, nên muốn sửa dữ liệu cũ thì phải làm lại toàn bộ các khối phía sau."]],"lesson":{"id":"E09","slug":"pre-transfer-checklist","ep":9,"title":"Trước khi chuyển coin: Tuyệt đối không đoán mò những điểm này"},"coin":null,"tool":null,"cta":false},"transaction-hash":{"slug":"transaction-hash","cat":"wallets-security","en":"Transaction hash (TxID)","contentLocale":"vi","term":"Mã giao dịch (Transaction hash, TxID)","aka":["TxID","TxHash","transaction hash","hash giao dịch"],"short":"Mã giao dịch (TxID hay TxHash) là chuỗi ký tự duy nhất định danh một giao dịch trên blockchain, dùng để tra cứu trạng thái, số tiền, phí và số xác nhận của giao dịch đó.","body":[["Mỗi khi bạn gửi crypto, giao dịch được băm thành một mã duy nhất, thường là chuỗi 64 ký tự hex, trên ",["Ethereum","ethereum"]," có thêm tiền tố 0x. Sàn sẽ hiển thị TxID trong lịch sử rút sau khi giao dịch được phát lên mạng."],["Dán TxID vào ",["trình khám phá khối","block-explorer"]," (block explorer) như Etherscan, Tronscan hay ",["mempool","mempool"],".space, bạn sẽ thấy giao dịch đang chờ, đã ",["xác nhận","block-confirmations"]," hay thất bại, đi từ địa chỉ nào đến địa chỉ nào, trên mạng nào."],"TxID là bằng chứng quan trọng nhất khi tiền chưa đến. Bộ phận hỗ trợ của sàn gần như luôn yêu cầu nó. TxID công khai, không cho phép ai chi tiêu tiền của bạn."],"example":["Giả sử bạn rút 0,02 ",["BTC","bitcoin"]," từ sàn về ví và sau 40 phút vẫn chưa thấy tiền. Bạn mở lịch sử rút, sao chép TxID, dán vào trình khám phá khối Bitcoin. Kết quả cho thấy giao dịch đã có 1 trên 3 xác nhận mà ví của bạn đang chờ, phí 0,00001 BTC, đúng địa chỉ của bạn. Bạn chỉ cần đợi thêm vài khối nữa."],"mistakes":["Gửi TxID trên Tronscan để tra một giao dịch thật ra đi trên mạng Ethereum.","Liên hệ hỗ trợ mà không gửi kèm TxID, khiến việc xử lý chậm hơn nhiều.","Tin vào ảnh chụp “đã chuyển tiền” của người lạ mà không tự tra TxID trên trình khám phá khối."],"faq":[{"q":"Tìm TxID ở đâu?","a":"Trong lịch sử rút hoặc chi tiết giao dịch trên sàn và trong ví. Nếu sàn chưa hiện TxID, thường là giao dịch chưa được phát lên blockchain."},{"q":"Có TxID mà vẫn chưa nhận tiền là sao?","a":"Giao dịch có thể đang chờ đủ số xác nhận, bị kẹt vì phí thấp, hoặc gửi sai mạng, sai memo. Tra TxID để biết đúng trạng thái."}],"title":"TxID là gì? Cách tra mã giao dịch blockchain","description":"Mã giao dịch TxID là gì, tìm ở đâu, cách tra trên block explorer và dùng TxID khi nạp rút crypto bị chậm.","related":[["block-explorer","Block explorer (trình khám phá khối)","Block explorer là trang web cho phép bạn tra cứu mọi giao dịch, địa chỉ ví và khối trên một blockchain, giống như công cụ tra cứu sao kê công khai của mạng đó."],["block-confirmations","Số xác nhận khối (Block confirmations)","Số xác nhận khối là số khối đã được thêm vào blockchain kể từ khối chứa giao dịch của bạn; càng nhiều xác nhận thì giao dịch càng khó bị đảo ngược."],["blockchain-network","Mạng nạp rút (Chọn mạng blockchain)","Mạng nạp rút là blockchain cụ thể mà một đồng coin được chuyển qua, ví dụ USDT có thể đi trên Tron (TRC20), Ethereum (ERC20) hay BNB Chain (BEP20); bên gửi và bên nhận phải dùng cùng mạng."],["mempool","Mempool (vùng chờ giao dịch)","Mempool là nơi các giao dịch đã được phát lên mạng nhưng chưa được đưa vào khối nằm chờ, trước khi thợ đào hoặc validator chọn để xác nhận."]],"lesson":{"id":"E10","slug":"transfer-not-arrived","ep":10,"title":"Báo đã gửi nhưng tiền chưa tới. Cần kiểm tra ở đâu?"},"coin":null,"tool":null,"cta":false},"address-poisoning":{"slug":"address-poisoning","cat":"wallets-security","en":"Address poisoning","contentLocale":"vi","term":"Đầu độc địa chỉ (Address poisoning)","aka":["address poisoning","lừa đảo địa chỉ giả"],"short":"Đầu độc địa chỉ là chiêu lừa đảo gửi giao dịch nhỏ từ một địa chỉ có đầu và cuối giống địa chỉ bạn hay dùng, để bạn sao chép nhầm từ lịch sử giao dịch và chuyển tiền cho kẻ gian.","body":[["Kẻ gian theo dõi ",["blockchain","blockchain"],", thấy bạn thường gửi tiền đến một địa chỉ. Chúng dùng máy tính tạo ra địa chỉ có vài ký tự đầu và cuối trùng khớp, rồi gửi vào ví bạn một khoản rất nhỏ, 0 token, hoặc token giả. Địa chỉ giả vì thế xuất hiện ngay trong lịch sử giao dịch của bạn."],["Lần sau, nếu bạn lười và sao chép địa chỉ từ lịch sử, chỉ liếc vài ký tự đầu cuối, rất dễ chọn nhầm địa chỉ giả. Kiểu tấn công này phổ biến với ",["USDT","usdt"]," và ",["USDC","usdc"]," trên ",["Ethereum","ethereum"],", Tron và các mạng phí rẻ."],"Cách phòng tránh: dùng sổ địa chỉ hoặc whitelist, sao chép địa chỉ từ nguồn gốc (trang nạp của sàn, ví nhận), so sánh toàn bộ chuỗi hoặc ít nhất phần giữa, và gửi thử khoản nhỏ."],"example":"Giả sử bạn thường gửi USDT đến ví sàn có địa chỉ TXa9…k7Pq. Hôm sau ví bạn nhận 0,001 USDT từ địa chỉ TXa9…k7Pq trông y hệt, nhưng phần giữa khác hẳn. Một tuần sau bạn cần gửi 5.000 USDT, sao chép dòng mới nhất trong lịch sử và suýt gửi đi. May mắn bạn so phần giữa với trang nạp của sàn, phát hiện sai và chặn được khoản mất 5.000 USDT.","mistakes":["Sao chép địa chỉ nhận từ lịch sử giao dịch thay vì từ sổ địa chỉ hoặc trang nạp.","Chỉ kiểm tra 4 ký tự đầu và 4 ký tự cuối của địa chỉ.","Tò mò tương tác với token lạ vừa được gửi vào ví."],"faq":[{"q":"Nhận giao dịch nhỏ từ địa chỉ lạ có bị mất tiền không?","a":"Bản thân việc nhận không làm mất tiền. Rủi ro chỉ xảy ra nếu sau đó bạn gửi tiền nhầm vào địa chỉ giả đó hoặc tương tác với token lạ."},{"q":"Gửi nhầm vào địa chỉ đầu độc có lấy lại được không?","a":"Gần như không, vì giao dịch blockchain không hoàn tác được. Bạn có thể báo cho sàn và đơn vị phát hành stablecoin, nhưng không có gì bảo đảm."}],"title":"Đầu độc địa chỉ là gì? Cách tránh gửi nhầm ví giả","description":"Đầu độc địa chỉ (address poisoning) là gì, kẻ gian tạo địa chỉ giả thế nào và các bước kiểm tra trước khi chuyển tiền.","related":[["wallet-address","Địa chỉ ví (Wallet address)","Địa chỉ ví là chuỗi ký tự công khai đại diện cho nơi nhận crypto trên một blockchain cụ thể, giống số tài khoản ngân hàng nhưng gắn với từng mạng lưới."],["withdrawal-whitelist","Danh sách trắng rút tiền (Withdrawal whitelist)","Danh sách trắng rút tiền là tính năng bảo mật chỉ cho phép tài khoản sàn rút crypto đến những địa chỉ bạn đã lưu và xác minh trước."],["phishing","Lừa đảo giả mạo (Phishing)","Phishing là hình thức lừa đảo giả mạo sàn, ví, dự án hoặc người quen để lừa bạn nhập mật khẩu, mã 2FA, cụm từ khôi phục hoặc ký giao dịch có hại."],["transaction-hash","Mã giao dịch (Transaction hash, TxID)","Mã giao dịch (TxID hay TxHash) là chuỗi ký tự duy nhất định danh một giao dịch trên blockchain, dùng để tra cứu trạng thái, số tiền, phí và số xác nhận của giao dịch đó."]],"lesson":{"id":"E09","slug":"pre-transfer-checklist","ep":9,"title":"Trước khi chuyển coin: Tuyệt đối không đoán mò những điểm này"},"coin":null,"tool":null,"cta":false},"token-approval":{"slug":"token-approval","cat":"wallets-security","en":"Token approval (allowance)","contentLocale":"vi","term":"Cấp quyền token (Token approval)","aka":["token approval","approve","allowance","cấp quyền chi tiêu"],"short":"Cấp quyền token là thao tác cho phép một hợp đồng thông minh được chi tiêu một lượng token nhất định trong ví của bạn, bắt buộc trước khi swap hay gửi token vào nhiều ứng dụng DeFi.","body":[["Trên ",["Ethereum","ethereum"]," và các mạng EVM, ",["DEX","dex"]," hay giao thức cho vay không thể tự lấy token từ ví bạn. Bạn phải ký giao dịch approve, đặt mức trần (allowance) mà hợp đồng được dùng. Nhiều ứng dụng mặc định xin quyền không giới hạn để bạn không phải approve lại mỗi lần."],["Rủi ro: quyền đã cấp vẫn còn hiệu lực sau khi bạn rời trang. Nếu hợp đồng bị hack, hoặc bạn approve cho hợp đồng lừa đảo, kẻ gian có thể rút token bất cứ lúc nào mà không cần thêm chữ ký. Các chữ ký kiểu Permit còn cấp quyền không tốn ",["phí gas","gas-fee"]," nên dễ bị ký nhầm."],["Hãy đặt mức approve vừa đủ khi ví cho phép, và định kỳ thu hồi quyền cũ bằng công cụ revoke hoặc ",["trình khám phá khối","block-explorer"],"."]],"example":["Giả sử bạn swap 100 ",["USDC","usdc"]," trên một DEX và ví đề xuất approve không giới hạn. Bạn sửa mức approve thành 100 USDC. Tháng sau hợp đồng của DEX đó bị khai thác lỗ hổng. Những người approve không giới hạn có thể mất toàn bộ USDC trong ví, còn quyền của bạn đã dùng hết nên 3.000 USDC còn lại vẫn an toàn."],"mistakes":["Approve không giới hạn cho mọi trang web mới mà không đọc tên hợp đồng.","Ký thông điệp Permit vì nghĩ rằng không tốn gas thì không nguy hiểm.","Không bao giờ kiểm tra và thu hồi các quyền cũ đã cấp."],"faq":[{"q":"Thu hồi quyền token có tốn phí không?","a":"Có, thu hồi là một giao dịch on-chain nên bạn phải trả phí gas của mạng đó."},{"q":"Approve có làm mất token ngay không?","a":"Không, approve chỉ cấp quyền. Token chỉ rời ví khi hợp đồng được cấp quyền thực hiện lệnh chuyển, vì vậy rủi ro nằm ở việc bạn cấp quyền cho ai."}],"title":"Token approval là gì? Cấp và thu hồi quyền ví","description":"Cấp quyền token (approve, allowance) là gì, vì sao approve không giới hạn nguy hiểm và cách thu hồi quyền cũ trong ví.","related":[["smart-contract","Hợp đồng thông minh (Smart contract)","Hợp đồng thông minh (smart contract) là chương trình được triển khai trên blockchain, tự động thực hiện các điều kiện đã lập trình khi có giao dịch gọi tới mà không cần bên trung gian."],["phishing","Lừa đảo giả mạo (Phishing)","Phishing là hình thức lừa đảo giả mạo sàn, ví, dự án hoặc người quen để lừa bạn nhập mật khẩu, mã 2FA, cụm từ khôi phục hoặc ký giao dịch có hại."],["non-custodial-wallet","Ví phi lưu ký (Non-custodial wallet)","Ví phi lưu ký là loại ví crypto mà bạn tự giữ khóa riêng tư và cụm từ khôi phục, nên chỉ bạn mới có quyền ký giao dịch và di chuyển tài sản."],["dex","Sàn phi tập trung (DEX)","Sàn phi tập trung (DEX) là nơi giao dịch crypto trực tiếp từ ví của bạn qua hợp đồng thông minh, không cần nạp tiền vào tài khoản của một công ty trung gian."]],"lesson":{"id":"E11","slug":"scam-red-flags","ep":11,"title":"Có người bảo giúp bạn kiếm tiền. Hãy xem họ đòi hỏi điều gì trước đã."},"coin":null,"tool":null,"cta":false},"dex":{"slug":"dex","cat":"defi","en":"Decentralized exchange (DEX)","contentLocale":"vi","term":"Sàn phi tập trung (DEX)","aka":["DEX","sàn DEX","decentralized exchange"],"short":"Sàn phi tập trung (DEX) là nơi giao dịch crypto trực tiếp từ ví của bạn qua hợp đồng thông minh, không cần nạp tiền vào tài khoản của một công ty trung gian.","body":[["Phần lớn DEX như Uniswap, PancakeSwap, Raydium dùng cơ chế ",["tạo lập thị trường tự động (AMM)","amm"],": bạn đổi token với ",["pool thanh khoản","liquidity-pool"]," thay vì khớp với người khác trên ",["sổ lệnh","order-book"],". Một số DEX khác, nhất là DEX ",["hợp đồng vĩnh cửu","perpetual-futures"],", dùng sổ lệnh on-chain."],["Ưu điểm: không cần ",["KYC","kyc"]," ở tầng giao thức, tự giữ tài sản, và token mới thường có mặt trên DEX trước ",["sàn tập trung","centralized-exchange"],". Nhược điểm: phải trả phí gas, trượt giá lớn với pool mỏng, dễ gặp token lừa đảo cùng tên, rủi ro hợp đồng và bot MEV chạy trước lệnh."],"Trên DEX, hãy kiểm tra địa chỉ hợp đồng token từ nguồn chính thức, đặt mức chấp nhận trượt giá hợp lý và để ý tác động giá trước khi bấm swap."],"example":"Giả sử bạn đổi 1.000 USDC lấy một token trên DEX. Màn hình báo bạn nhận khoảng 9.850 token, tác động giá 0,4%, phí pool 0,3%, phí gas ước tính 2 USD. Bạn đặt trượt giá tối đa 1%. Nếu giá biến động khiến bạn nhận ít hơn khoảng 9.751 token, giao dịch tự hủy và bạn chỉ mất phí gas.","mistakes":["Tìm token theo tên trên DEX và mua nhầm token giả cùng ký hiệu.","Đặt trượt giá quá cao như 20% để lệnh “chắc chắn khớp”, tạo cơ hội cho bot chạy trước.","Swap số tiền lớn trong pool thanh khoản mỏng mà không xem tác động giá."],"faq":[{"q":"DEX khác CEX như thế nào?","a":"CEX giữ tiền hộ bạn và khớp lệnh trên hệ thống nội bộ, còn DEX để bạn giao dịch trực tiếp từ ví qua hợp đồng thông minh. CEX thường có thanh khoản sâu và hỗ trợ, DEX cho bạn tự chủ và nhiều token hơn."},{"q":"Giao dịch trên DEX có cần KYC không?","a":"Bản thân hợp đồng không yêu cầu KYC, nhưng một số giao diện có thể chặn theo khu vực. Luật về nghĩa vụ thuế và báo cáo vẫn tùy từng quốc gia."}],"title":"DEX là gì? Sàn phi tập trung hoạt động thế nào","description":"Sàn phi tập trung DEX là gì, khác sàn tập trung CEX ra sao, cách swap an toàn và những rủi ro cần biết khi dùng DEX.","related":[["amm","Tạo lập thị trường tự động (AMM)","AMM (tạo lập thị trường tự động) là cơ chế của nhiều DEX dùng công thức toán học và pool thanh khoản để định giá và khớp giao dịch, thay cho sổ lệnh mua bán truyền thống."],["centralized-exchange","Sàn giao dịch tập trung (CEX)","Sàn giao dịch tập trung (CEX) là nền tảng do một công ty vận hành, giữ tài sản của người dùng và khớp lệnh mua bán trên sổ lệnh nội bộ, như Binance, OKX, Bybit hay Bitget."],["liquidity-pool","Pool thanh khoản (Liquidity pool)","Pool thanh khoản là kho token được khóa trong hợp đồng thông minh, do nhiều người cùng góp vào, để người khác giao dịch, vay hoặc swap, đổi lại người góp nhận một phần phí."],["slippage","Trượt giá (Slippage)","Trượt giá (slippage) là phần chênh lệch giữa giá bạn dự kiến khi đặt lệnh và giá khớp thực tế, xảy ra khi thanh khoản không đủ hoặc giá thay đổi trong lúc lệnh đang được xử lý."],["perp-dex","Perp DEX (Sàn hợp đồng vĩnh cửu phi tập trung)","Perp DEX là sàn phi tập trung cho phép giao dịch hợp đồng tương lai vĩnh cửu có đòn bẩy ngay trên blockchain, ký quỹ và thanh toán bằng ví của bạn thay vì tài khoản sàn tập trung."]],"lesson":null,"coin":{"slug":"uniswap","name":"Uniswap","symbol":"UNI"},"tool":"/compare","cta":false},"flash-loan":{"slug":"flash-loan","cat":"defi","en":"Flash loan","contentLocale":"vi","term":"Flash loan (Vay nhanh)","aka":["flash loan","vay chớp nhoáng","vay tức thời"],"short":"Flash loan là khoản vay không cần thế chấp trong DeFi, với điều kiện vay và trả cả gốc lẫn phí trong cùng một giao dịch; nếu không trả đủ, toàn bộ giao dịch bị hủy.","body":[["Một giao dịch ",["blockchain","blockchain"]," có thể gồm nhiều bước liên tiếp. Flash loan tận dụng điều đó: hợp đồng cho bạn vay ở bước đầu, bạn dùng tiền ở các bước giữa, và phải hoàn trả ở bước cuối. Nếu bước cuối thất bại, mọi bước trước đó bị đảo ngược như chưa từng xảy ra, nên bên cho vay gần như không chịu rủi ro."],["Ứng dụng hợp pháp gồm ",["arbitrage","arbitrage"]," giữa các ",["DEX","dex"],", đổi tài sản thế chấp, tự ",["thanh lý","liquidation"]," vị thế vay hoặc tái cấp vốn. Aave là một trong những giao thức phổ biến cung cấp flash loan."],["Flash loan cũng nổi tiếng vì được dùng trong nhiều vụ tấn công: kẻ tấn công vay số tiền rất lớn để thao túng giá trên pool mỏng mà một giao thức dùng làm ",["oracle","oracle"],". Flash loan không tạo ra lỗ hổng, nó chỉ khuếch đại lỗ hổng sẵn có."]],"example":["Giả sử ",["USDC","usdc"]," và một stablecoin khác lệch giá 0,3% giữa hai DEX. Một bot vay flash loan 1.000.000 USDC với phí giả định 0,05%, tức 500 USDC. Bot mua ở DEX rẻ, bán ở DEX đắt, thu về 1.003.000 USDC, trả 1.000.500 USDC. Trừ phí gas khoảng 50 USD, lãi khoảng 2.450 USD. Nếu chênh lệch biến mất giữa chừng, giao dịch thất bại và bot chỉ mất phí gas."],"mistakes":["Nghĩ rằng flash loan là cách vay tiền không thế chấp để giữ lâu dài.","Tin vào người rao bán “bot flash loan lợi nhuận chắc chắn”, thường là lừa đảo.","Đổ lỗi cho flash loan thay vì nhìn vào lỗ hổng oracle hoặc logic của giao thức bị tấn công."],"faq":[{"q":"Người bình thường có dùng flash loan được không?","a":"Có, nhưng cần viết hoặc dùng hợp đồng thông minh thực hiện toàn bộ các bước trong một giao dịch. Một số công cụ có giao diện sẵn cho các tác vụ như đổi thế chấp."},{"q":"Flash loan có rủi ro cho người vay không?","a":"Nếu giao dịch thất bại, bạn không mất khoản vay nhưng vẫn mất phí gas. Rủi ro lớn hơn nằm ở lỗi trong hợp đồng do chính bạn viết."}],"title":"Flash loan là gì? Vay không thế chấp trong DeFi","description":"Flash loan là gì, vì sao vay không cần thế chấp được, ứng dụng arbitrage và vai trò của flash loan trong các vụ tấn công DeFi.","related":[["defi-lending","Cho vay DeFi (DeFi lending)","Cho vay DeFi là việc gửi crypto vào giao thức như Aave để nhận lãi, hoặc thế chấp crypto để vay tài sản khác, toàn bộ do hợp đồng thông minh quản lý thay cho ngân hàng."],["oracle","Oracle (Nguồn dữ liệu blockchain)","Oracle là dịch vụ đưa dữ liệu bên ngoài như giá tài sản, kết quả sự kiện hay số ngẫu nhiên vào blockchain để hợp đồng thông minh sử dụng."],["mev","MEV (Giá trị khai thác tối đa)","MEV là phần lợi nhuận mà người sắp xếp giao dịch trong khối, như validator hay bot tìm kiếm, có thể thu được bằng cách chèn, sắp xếp lại hoặc loại bỏ giao dịch."],["smart-contract","Hợp đồng thông minh (Smart contract)","Hợp đồng thông minh (smart contract) là chương trình được triển khai trên blockchain, tự động thực hiện các điều kiện đã lập trình khi có giao dịch gọi tới mà không cần bên trung gian."]],"lesson":null,"coin":{"slug":"aave","name":"Aave","symbol":"AAVE"},"tool":null,"cta":false},"wrapped-token":{"slug":"wrapped-token","cat":"defi","en":"Wrapped token","contentLocale":"vi","term":"Token gói (Wrapped token)","aka":["wrapped token","WBTC","WETH","token wrapped"],"short":"Token gói là token đại diện cho một tài sản khác theo tỷ lệ 1:1, ví dụ WBTC đại diện cho BTC trên Ethereum, giúp tài sản đó dùng được trên blockchain hoặc trong ứng dụng vốn không hỗ trợ nó.","body":[[["Bitcoin","bitcoin"]," không chạy được ",["hợp đồng thông minh","smart-contract"]," của ",["Ethereum","ethereum"],", nên để dùng BTC trong ",["DeFi","defi"]," trên Ethereum, người ta gửi BTC thật cho một bên giữ hộ hoặc vào cơ chế khóa, rồi phát hành số WBTC tương ứng. Khi đổi ngược, WBTC bị đốt và BTC được trả lại."],"Một trường hợp khác là WETH: ETH gốc không theo chuẩn ERC-20, nên nhiều ứng dụng dùng WETH, phiên bản ERC-20 của ETH, được gói và mở gói bằng hợp đồng đơn giản 1:1 không cần bên giữ hộ.",["Rủi ro của token gói nằm ở thứ đảm bảo nó: bên giữ hộ, ",["cầu nối","cross-chain-bridge"]," hoặc hợp đồng. Nếu bên giữ hộ gặp sự cố hay cầu bị hack, token gói có thể ",["mất neo","depeg"]," so với tài sản gốc. Cùng tên nhưng token gói từ các cầu khác nhau không nhất thiết thay thế được cho nhau."]],"example":"Giả sử bạn có 0,5 BTC và muốn dùng làm thế chấp trên một giao thức cho vay Ethereum. Bạn đổi sang 0,5 WBTC, chịu phí đổi và phí gas. Với BTC ở mức giả định 60.000 USD, vị thế thế chấp trị giá 30.000 USD. Nếu WBTC giao dịch lệch xuống 0,98 BTC trong lúc thị trường lo ngại về bên giữ hộ, giá trị thế chấp giảm còn khoảng 29.400 USD dù giá BTC không đổi.","mistakes":["Gửi WBTC trên Ethereum vào địa chỉ nạp BTC mạng Bitcoin của sàn.","Nghĩ rằng token gói không có thêm rủi ro nào so với tài sản gốc.","Mua token gói không chính thức có cùng ký hiệu trên DEX mà không kiểm tra địa chỉ hợp đồng."],"faq":[{"q":"WETH và ETH khác nhau thế nào?","a":"Giá trị như nhau 1:1, nhưng WETH là token chuẩn ERC-20 để dùng thuận tiện trong hợp đồng thông minh. Bạn có thể gói và mở gói bất cứ lúc nào, chỉ tốn phí gas."},{"q":"Token gói có an toàn không?","a":"Tùy vào cơ chế đảm bảo. Token gói qua hợp đồng đơn giản như WETH ít rủi ro hơn token phụ thuộc vào bên giữ hộ hoặc cầu nối."}],"title":"Wrapped token là gì? WBTC, WETH hoạt động ra sao","description":"Token gói (wrapped token) là gì, WBTC và WETH hoạt động thế nào, vì sao cần token gói và rủi ro mất neo cần biết.","related":[["cross-chain-bridge","Cầu nối chuỗi chéo (Cross-chain bridge)","Cầu nối chuỗi chéo là giao thức giúp chuyển tài sản hoặc dữ liệu giữa hai blockchain khác nhau, thường bằng cách khóa tài sản ở chuỗi gốc và phát hành bản đại diện ở chuỗi đích."],["liquid-staking","Staking thanh khoản (Liquid staking)","Staking thanh khoản là cách stake coin qua một giao thức và nhận lại token đại diện như stETH, có thể giao dịch hoặc dùng trong DeFi trong khi coin gốc vẫn đang được stake."],["coin-vs-token","Coin và token (Coin vs token)","Coin là tài sản gốc của một blockchain riêng như BTC hay ETH, còn token là tài sản được tạo trên một blockchain có sẵn thông qua hợp đồng thông minh, như USDT trên Ethereum hay Tron."],["depeg","Depeg (mất neo giá)","Depeg là tình trạng một stablecoin hoặc token được neo giá rời khỏi mức giá mục tiêu của nó, ví dụ USDT hay USDC giao dịch ở 0,97 USD thay vì 1 USD."]],"lesson":null,"coin":{"slug":"bitcoin","name":"Bitcoin","symbol":"BTC"},"tool":null,"cta":false},"kyc":{"slug":"kyc","cat":"regulation","en":"KYC (know your customer)","contentLocale":"vi","term":"KYC (xác minh danh tính khách hàng)","aka":["KYC","xác minh danh tính","eKYC","Know Your Customer"],"short":"KYC là quy trình sàn giao dịch hoặc tổ chức tài chính xác minh danh tính người dùng bằng giấy tờ tùy thân, ảnh khuôn mặt và đôi khi là địa chỉ cư trú.","body":[["Hầu hết ",["sàn tập trung","centralized-exchange"]," lớn như Binance, OKX, Bybit hay Bitget yêu cầu KYC trước khi cho bạn nạp tiền pháp định, rút tiền hoặc dùng đầy đủ tính năng. Quy trình thường gồm chụp CCCD hoặc hộ chiếu, quay video khuôn mặt và đôi khi cung cấp giấy tờ chứng minh địa chỉ."],["KYC là một phần của nghĩa vụ ",["chống rửa tiền","aml"],". Nó giúp sàn chặn tài khoản giả, áp dụng giới hạn theo quốc gia và hỗ trợ bạn lấy lại tài khoản khi bị chiếm. Mức độ KYC và hạn mức rút có thể khác nhau tùy sàn và tùy cấp xác minh."],"Vì dữ liệu cá nhân rất nhạy cảm, chỉ thực hiện KYC trên ứng dụng hoặc trang chính thức. Không bao giờ gửi ảnh CCCD qua Telegram, Zalo hay cho người tự nhận là nhân viên hỗ trợ."],"example":["Giả sử sàn A cho tài khoản chưa KYC rút tối đa tương đương 1.000 USD mỗi ngày và chặn nạp ",["P2P","p2p-trading"],". Bạn hoàn tất KYC cơ bản bằng CCCD và ảnh khuôn mặt, hạn mức tăng lên, ví dụ 100.000 USD mỗi ngày, và bạn được dùng P2P. Sau đó bạn đổi số điện thoại mà quên cập nhật. Khi mất quyền truy cập, chính hồ sơ KYC giúp bộ phận hỗ trợ ",["xác nhận","block-confirmations"]," bạn là chủ tài khoản. Các con số trên chỉ minh họa, hạn mức thật xem trong trang xác minh của từng sàn."],"mistakes":["Gửi ảnh giấy tờ tùy thân cho người lạ tự xưng là hỗ trợ viên của sàn.","Mượn danh tính người khác để KYC, dễ dẫn tới khóa tài khoản và mất quyền rút tiền.","Khai báo quốc gia cư trú sai để vượt giới hạn khu vực."],"faq":[{"q":"Có bắt buộc KYC để giao dịch crypto không?","a":"Phần lớn sàn tập trung bắt buộc KYC để rút tiền hoặc dùng tiền pháp định. Ví tự lưu ký và DEX thường không yêu cầu, nhưng điểm nạp rút tiền pháp định gần như luôn cần KYC."},{"q":"KYC bị từ chối thì làm sao?","a":"Hãy kiểm tra ảnh có rõ, đủ bốn góc, không lóa và thông tin khớp với giấy tờ. Nếu vẫn bị từ chối, liên hệ hỗ trợ qua kênh chính thức trong ứng dụng."}],"title":"KYC là gì? Vì sao sàn crypto yêu cầu xác minh","description":"KYC là xác minh danh tính trên sàn crypto. Tìm hiểu quy trình, hạn mức, lý do bắt buộc và cách bảo vệ dữ liệu cá nhân.","related":[["aml","AML (phòng chống rửa tiền)","AML là tập hợp quy định và quy trình mà sàn giao dịch và tổ chức tài chính áp dụng để phát hiện, ngăn chặn và báo cáo hoạt động rửa tiền hoặc tài trợ khủng bố."],["travel-rule","Travel rule (quy tắc chuyển tiền)","Travel rule là quy định yêu cầu các nhà cung cấp dịch vụ tài sản ảo gửi kèm thông tin người gửi và người nhận khi chuyển crypto giữa các tổ chức với nhau."],["no-kyc-exchange","Sàn không KYC","Sàn không KYC là nơi cho phép giao dịch hoặc rút crypto mà không cần xác minh danh tính, thường trong một hạn mức nhất định hoặc thông qua mô hình phi tập trung."],["centralized-exchange","Sàn giao dịch tập trung (CEX)","Sàn giao dịch tập trung (CEX) là nền tảng do một công ty vận hành, giữ tài sản của người dùng và khớp lệnh mua bán trên sổ lệnh nội bộ, như Binance, OKX, Bybit hay Bitget."],["vasp","VASP (nhà cung cấp dịch vụ tài sản ảo)","VASP là tổ chức cung cấp dịch vụ liên quan đến tài sản ảo cho người khác, như sàn giao dịch, dịch vụ lưu ký hoặc chuyển đổi crypto, và chịu các nghĩa vụ quản lý như KYC, AML."]],"lesson":{"id":"E05","slug":"kyc-who-gets-your-id","ep":5,"title":"KYC thực hiện như thế nào và ai mới là người nhận giấy tờ của bạn?"},"coin":null,"tool":null,"cta":false},"demo-trading":{"slug":"demo-trading","cat":"exchange-features","en":"Demo trading","contentLocale":"vi","term":"Giao dịch demo (tài khoản thử)","aka":["demo trading","tài khoản demo","giao dịch giả lập","paper trading"],"short":"Giao dịch demo là chế độ giao dịch bằng tiền ảo trên giao diện giống thật, giúp bạn luyện thao tác đặt lệnh, dùng đòn bẩy và quản lý rủi ro mà không mất tiền thật.","body":[["Nhiều sàn như OKX, Bybit, Bitget và Binance có chế độ demo hoặc testnet cho ",["hợp đồng tương lai","futures-contract"],", đôi khi cả spot và bot. Bạn nhận một số dư ảo và có thể nạp lại khi hết. Giá thường bám theo thị trường thật, nhưng độ sâu ",["sổ lệnh","order-book"]," và tốc độ khớp có thể khác."],["Demo là nơi tốt để học cách đặt ",["lệnh giới hạn","limit-order"],", ",["cắt lỗ","stop-loss"],", ",["chốt lời","take-profit"],", tính ",["giá thanh lý","liquidation-price"]," và so sánh ký quỹ cô lập với ký quỹ chéo. Bạn hiểu được một con số đòn bẩy có ý nghĩa gì mà không phải trả học phí bằng tiền thật."],"Hạn chế lớn nhất là tâm lý. Thua tiền ảo không đau, nên nhiều người giao dịch táo bạo hơn hẳn. Khi chuyển sang tiền thật, hãy bắt đầu với số vốn nhỏ và giữ nguyên quy tắc đã luyện."],"example":"Giả sử tài khoản demo có 50.000 USDT ảo. Bạn mở long BTC với ký quỹ 5.000 USDT và đòn bẩy 10 lần, vị thế trị giá 50.000 USDT. BTC giảm 8%, vị thế lỗ 4.000 USDT, tức 80% ký quỹ, và giá thanh lý đã rất gần. Nếu đặt cắt lỗ ở mức giảm 3%, bạn chỉ lỗ khoảng 1.500 USDT. Trải nghiệm này trên demo giúp bạn hiểu đòn bẩy mà không mất đồng nào.","mistakes":["Giao dịch demo với đòn bẩy tối đa vì nghĩ không có gì để mất, rồi mang thói quen đó sang tiền thật.","Cho rằng lợi nhuận trên demo sẽ lặp lại y hệt với tiền thật.","Chỉ luyện vài ngày rồi chuyển ngay sang vốn lớn."],"faq":[{"q":"Lời trên tài khoản demo có rút được không?","a":"Không. Số dư demo là tiền ảo, chỉ dùng để luyện tập và không thể rút hay chuyển sang tài khoản thật."},{"q":"Nên luyện demo bao lâu trước khi giao dịch thật?","a":"Không có con số cố định. Hãy luyện cho tới khi bạn đặt lệnh, cắt lỗ và tính giá thanh lý thành thạo, rồi bắt đầu thật với vốn nhỏ."}],"title":"Giao dịch demo là gì? Luyện trade futures bằng tiền ảo","description":"Giao dịch demo cho phép luyện lệnh, đòn bẩy và cắt lỗ bằng tiền ảo. Tìm hiểu cách dùng hiệu quả và giới hạn của tài khoản demo.","related":[["perpetual-futures","Hợp đồng tương lai vĩnh cửu (Perpetual)","Hợp đồng tương lai vĩnh cửu (perpetual) là hợp đồng tương lai không có ngày đáo hạn, dùng cơ chế funding rate để giữ giá hợp đồng bám sát giá spot."],["leverage","Đòn bẩy (Leverage)","Đòn bẩy là việc dùng một khoản ký quỹ nhỏ để mở vị thế có giá trị lớn hơn nhiều lần, làm phóng đại cả lợi nhuận lẫn thua lỗ."],["copy-trading","Copy trade (sao chép giao dịch)","Copy trade là tính năng cho phép bạn tự động sao chép các lệnh của một nhà giao dịch khác, gọi là trader dẫn dắt, theo tỷ lệ vốn mà bạn phân bổ."],["position-sizing","Quản lý khối lượng vị thế (Position sizing)","Position sizing là cách xác định bạn nên mở một lệnh lớn bao nhiêu, dựa trên số tiền bạn chấp nhận mất nếu lệnh chạm cắt lỗ."]],"lesson":{"id":"E19","slug":"what-leverage-does","ep":19,"title":"Đòn bẩy 10x: tiền nhiều hơn hay rủi ro lớn hơn?"},"coin":null,"tool":null,"cta":true}});
